from collections import deque

def next_greater(nums: list[int]) -> list[int]:
    ans, stack = [-1] * len(nums), []   # stack: indexes, values decreasing
    for i, x in enumerate(nums):
        while stack and nums[stack[-1]] < x:
            ans[stack.pop()] = x        # x is the first greater value for that index
        stack.append(i)
    return ans

def window_max(nums: list[int], k: int) -> list[int]:
    dq, out = deque(), []               # dq: indexes, values decreasing
    for i, x in enumerate(nums):
        while dq and nums[dq[-1]] <= x:
            dq.pop()                    # smaller and older: never a max again
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()                # front slid out of the window
        if i >= k - 1:
            out.append(nums[dq[0]])
    return out

def balanced(s: str) -> bool:
    pairs, stack = {")": "(", "]": "[", "}": "{"}, []
    for ch in s:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs and (not stack or stack.pop() != pairs[ch]):
            return False
    return not stack
